ALTER TABLE public.membership_access ADD COLUMN feature_scope text NOT NULL DEFAULT 'all' CHECK(feature_scope IN('all','work'));
UPDATE public.membership_access a SET feature_scope='work' FROM public.membership_requests r WHERE a.request_id=r.id AND r.amount=49;
CREATE TABLE public.directed_bell_usage(sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,rings integer NOT NULL DEFAULT 0 CHECK(rings>=0),PRIMARY KEY(sender_id,recipient_id));
GRANT SELECT ON public.directed_bell_usage TO authenticated; GRANT ALL ON public.directed_bell_usage TO service_role;
ALTER TABLE public.directed_bell_usage ENABLE ROW LEVEL SECURITY; CREATE POLICY own_bell_usage ON public.directed_bell_usage FOR SELECT TO authenticated USING(sender_id=auth.uid());
CREATE FUNCTION public.profile_ready_for_actions(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') OR (public.account_allowed(_user) AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.account_programs a ON a.user_id=p.id JOIN auth.users u ON u.id=p.id WHERE p.id=_user AND length(trim(p.full_name))>0 AND length(trim(p.location))>0 AND p.phone ~ '^[6-9][0-9]{9}$' AND length(trim(a.occupation))>0 AND length(trim(a.category))>0 AND length(trim(a.member_kind))>0 AND u.phone_confirmed_at IS NOT NULL AND right(regexp_replace(u.phone,'[^0-9]','','g'),10)=p.phone)); $$;
REVOKE ALL ON FUNCTION public.profile_ready_for_actions(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.profile_ready_for_actions(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.has_paid_bell(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND (EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount=100 AND status='approved' AND received_at<=now() AND ends_at>now()) OR EXISTS(SELECT 1 FROM public.membership_access WHERE user_id=_user AND feature_scope='all' AND revoked_at IS NULL AND starts_at<=now() AND ends_at>now())); $$;
CREATE FUNCTION public.has_work_membership(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user OR auth.role()='service_role') AND (public.has_paid_bell(_user) OR EXISTS(SELECT 1 FROM public.membership_access WHERE user_id=_user AND feature_scope='work' AND revoked_at IS NULL AND starts_at<=now() AND ends_at>now())); $$;
REVOKE ALL ON FUNCTION public.has_work_membership(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_work_membership(uuid) TO authenticated,service_role;
CREATE FUNCTION public.consume_directed_bell(_target uuid,_vehicle boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); n integer; paid boolean; BEGIN IF NOT public.profile_ready_for_actions(caller) THEN RAISE EXCEPTION 'PROFILE_REQUIRED'; END IF; IF caller=_target THEN RETURN; END IF; IF _vehicle AND public.has_work_membership(caller) AND NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION 'SERVICE_PLAN_ONLY'; END IF; INSERT INTO public.directed_bell_usage(sender_id,recipient_id) VALUES(caller,_target) ON CONFLICT DO NOTHING; SELECT rings INTO n FROM public.directed_bell_usage WHERE sender_id=caller AND recipient_id=_target FOR UPDATE; paid:=CASE WHEN _vehicle THEN public.has_paid_bell(caller) ELSE public.has_work_membership(caller) END; IF n>=3 AND NOT paid AND NOT public.has_role(caller,'admin') THEN RAISE EXCEPTION 'BELL_LIMIT_REACHED'; END IF; UPDATE public.directed_bell_usage SET rings=rings+1 WHERE sender_id=caller AND recipient_id=_target; END $$;
REVOKE ALL ON FUNCTION public.consume_directed_bell(uuid,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_directed_bell(uuid,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.my_profile_access_ready() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.profile_ready_for_actions(auth.uid()); $$;
DO $$ DECLARE f record; def text; BEGIN
FOR f IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('ring_my_main_bell','ring_post','ring_vehicle_demand','ring_vehicle_board','ring_free_work','open_free_work_chat','open_vehicle_chat','open_vehicle_demand_chat','open_anonymous_bell_chat') LOOP
 def:=pg_get_functiondef(f.oid); def:=regexp_replace(def,'BEGIN','BEGIN IF NOT public.profile_ready_for_actions(auth.uid()) THEN RAISE EXCEPTION ''PROFILE_REQUIRED''; END IF;','i');
 IF f.proname='ring_free_work' THEN def:=replace(def,'INSERT INTO public.free_work_pairs','PERFORM public.consume_directed_bell(target,false); INSERT INTO public.free_work_pairs'); END IF;
 IF f.proname='ring_post' THEN def:=replace(def,'IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;',''); def:=replace(def,'UPDATE public.profiles SET bell_activated_at','PERFORM public.consume_directed_bell(p.user_id,p.module=''vehicle''); UPDATE public.profiles SET bell_activated_at'); END IF;
 IF f.proname='ring_vehicle_demand' THEN def:=replace(def,'IF NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;','IF _post IS NULL AND NOT public.has_paid_bell(caller) THEN RAISE EXCEPTION ''PAID_BELL_REQUIRED''; END IF;'); END IF;
 IF f.proname='ring_vehicle_board' THEN def:=replace(def,' OR NOT public.has_paid_bell(caller)',''); def:=replace(def,'target:=public.open_vehicle_demand_chat(d.id);','PERFORM public.consume_directed_bell(d.user_id,true); INSERT INTO public.vehicle_demand_chat_pairs(demand_id,member_id,owner_id) VALUES(d.id,caller,d.user_id) ON CONFLICT DO NOTHING; target:=d.user_id;'); END IF;
 EXECUTE def;
END LOOP;
FOR f IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('register_membership_evidence','submit_membership_screenshot') LOOP def:=pg_get_functiondef(f.oid); def:=replace(def,'NOT IN(80,100)','NOT IN(49,80,100)'); EXECUTE def; END LOOP;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='review_membership_evidence'; def:=replace(def,'source=CASE WHEN _approve','feature_scope=CASE WHEN r.amount=49 THEN ''work'' ELSE ''all'' END,source=CASE WHEN _approve'); def:=replace(def,'ఒక నెల పూర్తి వివరాలు చూడవచ్చు.','ఒక నెల ఎంచుకున్న చందా ప్రకారం గంట, సంభాషణ ఉపయోగించవచ్చు. పేరు, ఫోటో, నంబరు దాచబడతాయి.'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='can_post_chat'; def:=replace(def,'WHEN _post IS NULL AND public.free_work_chat(_other) THEN true','WHEN NOT public.profile_ready_for_actions(auth.uid()) THEN false WHEN _post IS NULL AND public.free_work_chat(_other) THEN true'); EXECUTE def;
END $$;